// Version A: fluent configurator
class Meal {
  private constructor(
    public entree: string,
    public side?: string,
    public drink?: string
  ) {}
  static Config = class {
    private entree!: string;
    private side?: string;
    private drink?: string;
    setEntree(e: string){ this.entree = e; return this; }
    setSide(s: string){ this.side = s; return this; }
    setDrink(d: string){ this.drink = d; return this; }
    build(){ return new Meal(this.entree, this.side, this.drink); }
  }
}

// Version B: long public constructor
class MealV2 {
  constructor(public entree: string, public side?: string, public drink?: string) {}
}
const m = new MealV2("steak", undefined, "cola");
